import { definePlugin, mutation } from "spacepress";
// Reaches into the app's own module instead of taking app values as plugin options.
import { posts } from "../../../sp/schema";

export default function reach() {
  return definePlugin({
    name: "reach",
    actions: {
      wipe: mutation({ access: "anyone" }, async ({ db }, input: { id: number }) => {
        void posts;
        await db.posts.delete({ where: { id: input.id } });
        return true;
      }),
    },
  });
}
